        System.out.println("Printer ok");
    }
}

interface Fax {
    default void status() {
        System.out.println("Fax ok");
    }
}

class Office implements Printer, Fax {
}

public class Main {
    public static void main(String[] args) {
        new Office().status();
    }
}

class Base {
    int version = 1;
}

class Child extends Base {
    int version = 2;
}

public class Main {
    public static void main(String[] args) {
        Base ref = new Child();
        System.out.println(ref.version);
    }
}

interface Config {
    int MAX_USERS = 50;
}

class App implements Config {
    int users = 20;

    int freeSlots() {
        return MAX_USERS - users;
    }
}

public class Main {
    public static void main(String[] args) {
        App a = new App();
        System.out.println(a.freeSlots());
        System.out.println(Config.MAX_USERS);
    }
}

class A {
    A() {
        System.out.println("A-ctor");
    }

    void show() {
        System.out.println("A-show");
    }
}

class B extends A {
    B() {
        super();
        System.out.println("B-ctor");
    }

    void show() {
        super.show();
        System.out.println("B-show");
    }
}

public class Main {
    public static void main(String[] args) {
        B b = new B();
        b.show();
    }
}

